        cameras = []
        lights = []
        renderable_prims = 0
        unassigned_material_prims = []
        unresolved_references = []
        prims = []

        for prim in stage.Traverse():
            if len(prims) >= limit:
                break
            path_str = str(prim.GetPath())
            type_name = str(prim.GetTypeName())
            prims.append({"path": path_str, "type": type_name})

            if _has_pxr:
