            "prims": prims,
            "cameras": sorted(cameras),
            "lights": sorted(lights),
            "renderable_prims": renderable_prims,
            "unassigned_material_prims": sorted(unassigned_material_prims)[:50],
            "unresolved_references": unresolved_references[:20],
